```gdscript
extends KinematicBody

var speed = 100
var jump_speed = -350
var gravity = 10
var max_speed = 50
var ground_check_size = Vector2(0,1)

onready var camera = $Camera

func _physics_process(delta):
    var velocity = kinematic_velocity
    if Input.is_action_pressed("move_left"):
        velocity -= speed * delta
    elif Input.is_action_pressed("move_right"):
        velocity += speed * delta
    else:
        velocity.x = lerp(velocity.x, 0, 0.1)

    velocity.y += gravity

    if velocity.y > max_speed:
        velocity.y = max_speed

    if (ground_check_size.x == 0 && ground_check_size.y == 1) || (ground_check_size.x == 0 && ground_check_size.y == -1):
        if is_on_ground():
            jump()

func jump():
    if state == "Jump":
        return
    state = "Jump"
    velocity.y += jump_speed
```

